import { BrowserWindow, Tray, nativeImage, nativeTheme, screen } from 'electron';
import path from 'node:path';
import { computePopupPosition } from './popup-position';
import { POPUP_HEIGHT, POPUP_WIDTH } from './popup-layout';

// Ticket-card icon — black on transparent, used as a macOS template image so
// the OS automatically renders it correctly in both light and dark menu bars.
// Generated by: node scripts/generate-icons.mjs (source: src/assets/tray-icon.svg)
const TRAY_ICON_1X =
  '';
const TRAY_ICON_2X =
  '';

// Alert variant (light menu bar) — black icon strokes + orange dot.
// Alert variant (dark menu bar)  — white icon strokes + orange dot.
// Not template images so the dot colour is preserved.
// Generated by: node scripts/generate-icons.mjs (sources: src/assets/tray-icon-alert*.svg)
const TRAY_ICON_ALERT_1X =
  '';
const TRAY_ICON_ALERT_2X =
  '';
const TRAY_ICON_ALERT_DARK_1X =
  '';
const TRAY_ICON_ALERT_DARK_2X =
  '';

// ── Icon creation ───────────────────────────────────────────────────────────

function buildDefaultIcon() {
  const img = nativeImage.createEmpty();
  img.addRepresentation({ scaleFactor: 1, buffer: Buffer.from(TRAY_ICON_1X, 'base64') });
  img.addRepresentation({ scaleFactor: 2, buffer: Buffer.from(TRAY_ICON_2X, 'base64') });
  img.setTemplateImage(true);
  return img;
}

function buildAlertIcon(dark: boolean) {
  // Same ticket icon with an orange dot — not a template image so the dot colour is preserved.
  // Two variants: black strokes for light menu bar, white strokes for dark menu bar.
  const img = nativeImage.createEmpty();
  if (dark) {
    img.addRepresentation({ scaleFactor: 1, buffer: Buffer.from(TRAY_ICON_ALERT_DARK_1X, 'base64') });
    img.addRepresentation({ scaleFactor: 2, buffer: Buffer.from(TRAY_ICON_ALERT_DARK_2X, 'base64') });
  } else {
    img.addRepresentation({ scaleFactor: 1, buffer: Buffer.from(TRAY_ICON_ALERT_1X, 'base64') });
    img.addRepresentation({ scaleFactor: 2, buffer: Buffer.from(TRAY_ICON_ALERT_2X, 'base64') });
  }
  return img;
}

// ── Popup visibility ────────────────────────────────────────────────────────
//
// The popup window is never hidden for real. macOS plays a window-open "pop"
// (a brief scale-up with a fade) every time a hidden window is ordered back
// in, which makes the popup look like it resizes and re-renders on every open.
// Instead the window stays ordered in at all times and is "closed" by making
// it fully transparent and click-through, "opened" by reversing that. Changing
// the window opacity doesn't trigger the system animation.

const openPopups = new WeakSet<BrowserWindow>();

export function isPopupOpen(win: BrowserWindow): boolean {
  return openPopups.has(win);
}

function closePopup(win: BrowserWindow): void {
  openPopups.delete(win);
  win.setOpacity(0);
  win.setIgnoreMouseEvents(true);
}

function openPopup(win: BrowserWindow, position: { x: number; y: number }): void {
  openPopups.add(win);
  win.setPosition(position.x, position.y);
  win.setIgnoreMouseEvents(false);
  win.setOpacity(1);
  win.focus();
}

// ── Public API ──────────────────────────────────────────────────────────────

export function createPopupWindow(opts: {
  devServerUrl: string | undefined;
  filePath: string;
}): BrowserWindow {
  const win = new BrowserWindow({
    width: POPUP_WIDTH,
    height: POPUP_HEIGHT,
    show: false,
    frame: false,
    resizable: false,
    alwaysOnTop: true,
    skipTaskbar: true,
    transparent: true,
    backgroundColor: '#00000000',
    vibrancy: 'under-window',
    roundedCorners: true,
    webPreferences: {
      preload: path.join(__dirname, 'preload.cjs'),
      contextIsolation: true,
      nodeIntegration: false,
    },
  });

  // Start closed: invisible and click-through, but ordered in (see above).
  win.setOpacity(0);
  win.setIgnoreMouseEvents(true);
  // Without this the always-ordered-in window would stay on the Space it was
  // created in, and opening the popup from another Space would switch back to it.
  win.setVisibleOnAllWorkspaces(true, {
    visibleOnFullScreen: true,
    skipTransformProcessType: true,
  });
  win.showInactive();

  if (opts.devServerUrl) {
    void win.loadURL(opts.devServerUrl);
  } else {
    void win.loadFile(opts.filePath);
  }

  return win;
}

export function createTray(
  popupWindow: BrowserWindow,
  opts: { onShow: () => void },
): { tray: Tray; updateBadge: (count: number) => void } {
  // On macOS, clicking the tray icon while the popup is open fires `blur` on
  // the popup first (hiding it), then fires `tray.click`. Without a guard the
  // click handler would see the popup as closed and reopen the window instead
  // of treating the click as a close-toggle. We record the hide timestamp so
  // the click handler can skip the reopen if it arrives within 200 ms.
  let hiddenAt = 0;

  popupWindow.on('blur', () => {
    if (!isPopupOpen(popupWindow)) return;
    hiddenAt = Date.now();
    closePopup(popupWindow);
  });

  const defaultIcon = buildDefaultIcon();

  const tray = new Tray(defaultIcon);
  tray.setToolTip('Jira Tray');

  let badgeCount = 0;

  function applyIcon(): void {
    if (badgeCount > 0) {
      tray.setImage(buildAlertIcon(nativeTheme.shouldUseDarkColors));
    } else {
      tray.setImage(defaultIcon);
    }
  }

  // Re-apply the alert icon whenever the system theme changes (light ↔ dark).
  nativeTheme.on('updated', applyIcon);

  tray.on('click', (_event, bounds) => {
    const BLUR_CLICK_GUARD_MS = 200;
    const closedByBlur =
      !isPopupOpen(popupWindow) && Date.now() - hiddenAt < BLUR_CLICK_GUARD_MS;
    if (closedByBlur) return;

    if (isPopupOpen(popupWindow)) {
      closePopup(popupWindow);
      return;
    }

    const display = screen.getDisplayNearestPoint({
      x: bounds.x,
      y: bounds.y,
    });
    const { width, height } = popupWindow.getBounds();
    const { x, y } = computePopupPosition(
      bounds,
      { width, height },
      display.workArea,
    );
    openPopup(popupWindow, { x, y });
    popupWindow.webContents.send('window-show');
    opts.onShow();
  });

  function updateBadge(count: number): void {
    badgeCount = count;
    applyIcon();
  }

  return { tray, updateBadge };
}
